import datetime
from ute_btssm.templatesession import new_session
from .base_btssm import BaseBtssmInterface


class SnapshotInterface(BaseBtssmInterface):
    """Keywords related to BTS SM saving/downloading snapshot."""
    FLAG = ['savesnapshot']

    def save_snapshot(self, logcoverage='all', snapshotfilename=None, notes=None, notesfile=None,
                      cancel_after=None, lnceldn=None, **kwargs):
        """Saves the snapshot with desired filename into specified location, supported since (xL16A/xLF16A/xLC16A/xLAP16A).

        :param string logcoverage: possible values (most | all).
        :param string snapshotfilename: The name of the output snapshot file with (optional) path. default directory ('/tmp/').
        :param string notes: The text string to be added to the Notes field in the snapshot description file.
        :param string notesfile: Name of the file with (optional) path that includes the text to be added to the Notes field.
        :param int cancel_after: Saving operation is cancelled after this time [ 1 ... 7200(default)].
        :param string lnceldn: List of distnames to specify from which FZAPs will the snapshot be collected.
        |

        :Other supported parameter available via kwargs:
            * **timeout**  - Execution timeout in case snapshot saving process takes too long to finish.
                             Can be specified in human format like 5s, 10minutes, 1min 5s.
                             Timeout is assumed to be in seconds if value is integer or float.
        """
        time_now = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
        snapshotfilename = "/tmp/Snapshot_{}.zip".format(time_now) if not snapshotfilename else snapshotfilename
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        notes = '"{}"'.format(notes)
        params = {'ne': ne, 'pw': pw, 'logcoverage': logcoverage, 'snapshotfilename': snapshotfilename, 'notes': notes,
                  'notesfile': notesfile, 'cancelAfter': cancel_after, 'lnceldn': lnceldn}
        timeout = self._convert_to_secs(kwargs.get('timeout'))
        with new_session.NewSession(alias, config) as session:
            session.btssm.save_snapshot(params, self.FLAG, timeout=timeout)
